/* Bounded probes copied from the pinned BOR.C gameplay expressions. */
#include <stdio.h>
#include <string.h>

static unsigned bits(float value){
    unsigned result;
    memcpy(&result, &value, sizeof(result));
    return result;
}

static float source_randf(unsigned long r, float max){
    float f;
    if(max==0) return 0;
    f = (r % 1000);
    f /= (1000/max);
    return f;
}

static void source_gravity(void){
    float a=240.0, base=0.0, tossv=1.0;
    unsigned i;
    for(i=0;i<70;i++){
        a += tossv;
        if(tossv > -6) tossv -= 0.1;
        if(a <= base) a = base;
    }
    printf("gravity a=%08x v=%08x branch=%u\n", bits(a), bits(tossv), tossv>-6);
}

static void source_anything_walk(void){
    float x=20.0, speed=0.9, xdir;
    unsigned i;
    xdir = speed + source_randf(0, 3.0);
    for(i=0;i<10;i++) x += xdir;
    printf("anything_walk x=%08x pixel=%d xdir=%08x\n", bits(x), (int)x, bits(xdir));
}

static void source_inair(void){
    float a=1.0, base=0.0;
    printf("inair a=%08x result=%u\n", bits(a), (a<base ? base-a : a-base)>=0.1);
}

int main(void){
    source_gravity();
    source_anything_walk();
    source_inair();
    printf("casts +1.9=%d -1.9=%d\n", (int)1.9, (int)-1.9);
    return 0;
}

