/* Isolated expressions copied from the pinned BOR gameplay paths. */
float bor_randf(unsigned long r, float max){
    float f;
    if(max==0) return 0;
    f = r % 1000;
    f /= (1000/max);
    return f;
}

float bor_gravity(float a, float v, float base){
    a += v;
    if(v > -6) v -= 0.1;
    if(a <= base) a = base;
    return a + v;
}

float bor_drift(float x, float speed, unsigned long r){
    return x + speed + (3 * (r % 1000)) / (1000 / speed);
}

int bor_cast(float value){ return (int)value; }

float bor_diff(float a, float b){
    if(a < b) return b-a;
    return a-b;
}
